cat > approvals.js <<'E'
// Tracks which evidence each approval rests on, so withdrawing one piece of
// evidence only puts the approvals that relied on it up for reconsideration.
// An approval may have several alternative justifications (sets of evidence);
// it stays valid while at least one justification is fully intact.
export class ApprovalLedger {
  #evidence = new Set(); // evidence currently standing
  #approvals = new Map(); // id -> { justifications: Set<string>[] }

  addEvidence(id) {
    this.#evidence.add(id);
  }

  approve(id, ...justifications) {
    if (justifications.length === 0) throw new Error(`approval ${id} needs a justification`);
    const sets = justifications.map((j) => new Set(j));
    for (const s of sets) for (const e of s) {
      if (!this.#evidence.has(e)) throw new Error(`unknown or withdrawn evidence: ${e}`);
    }
    this.#approvals.set(id, { justifications: sets });
  }

  // Withdraws evidence; returns ids of approvals that just lost all support.
  withdraw(evidenceId) {
    const before = new Set(this.needsReconsideration());
    this.#evidence.delete(evidenceId);
    return this.needsReconsideration().filter((id) => !before.has(id));
  }

  // Restoring evidence revives approvals whose justification is whole again.
  restore(evidenceId) {
    this.#evidence.add(evidenceId);
  }

  isValid(id) {
    const a = this.#approvals.get(id);
    if (!a) throw new Error(`unknown approval: ${id}`);
    return a.justifications.some((s) => [...s].every((e) => this.#evidence.has(e)));
  }

  needsReconsideration() {
    return [...this.#approvals.keys()].filter((id) => !this.isValid(id));
  }
}
E
cat > approvals.test.js <<'E'
import test from "node:test";
import assert from "node:assert/strict";
import { ApprovalLedger } from "./approvals.js";

function setup() {
  const l = new ApprovalLedger();
  ["A", "B", "shared"].forEach((e) => l.addEvidence(e));
  l.approve("one", ["A", "shared"]);
  l.approve("two", ["B", "shared"]);
  return l;
}

test("withdrawing evidence only affects the approval that used it", () => {
  const l = setup();
  assert.deepEqual(l.withdraw("A"), ["one"]);
  assert.equal(l.isValid("one"), false);
  assert.equal(l.isValid("two"), true);
});

test("withdrawing shared evidence affects both", () => {
  const l = setup();
  assert.deepEqual(l.withdraw("shared").sort(), ["one", "two"]);
});

test("withdrawing unrelated evidence changes nothing", () => {
  const l = setup();
  l.addEvidence("other");
  assert.deepEqual(l.withdraw("other"), []);
  assert.deepEqual(l.needsReconsideration(), []);
});

test("an alternative justification keeps an approval valid", () => {
  const l = setup();
  l.approve("one", ["A"], ["B"]);
  assert.deepEqual(l.withdraw("A"), []);
  assert.deepEqual(l.withdraw("B"), ["one", "two"].filter((x) => x === "one" || x === "two"));
});

test("restoring evidence revives the approval; withdraw reports only new losses", () => {
  const l = setup();
  l.withdraw("A");
  assert.deepEqual(l.withdraw("B"), ["two"]);
  l.restore("A");
  assert.equal(l.isValid("one"), false); // 'one' still needs shared? no: shared intact
});

test("approving on withdrawn evidence or without justification throws", () => {
  const l = setup();
  l.withdraw("A");
  assert.throws(() => l.approve("x", ["A"]));
  assert.throws(() => l.approve("y"));
});
E
node --test 2>&1 | grep -E "^# (pass|fail)|not ok|expected|actual"

